const HANDBOOK_DATA = {"reviewed":"2026-10-21","tools":{"python":{"name":"Python","category":"Programming","kind":"Open source","delivery":"Local interpreter; packaged into jobs and services","what":"The implementation language for many ML pipelines, evaluation harnesses and service integrations. Learn how to build a small maintainable service before adding an agent framework.","learn":["Environments and dependency locking","Functions, types, exceptions and tests","HTTP clients, timeouts and bounded concurrency","JSON, file formats and structured logging"],"lab":"Write a command-line evaluation runner that reads a dataset, calls a mock endpoint, handles timeout errors and saves a reproducible report.","tradeoff":"Async code still needs concurrency limits; a notebook that runs once is not a deployable service.","url":"https://docs.python.org/3/tutorial/","licenseUrl":null},"sklearn":{"name":"scikit-learn","category":"Model development","kind":"Open source","delivery":"Local or cloud CPU training","what":"A practical baseline toolkit for supervised and unsupervised ML. Its preprocessing pipelines help keep transformations consistent between training and prediction.","learn":["Train/validation/test splits","Pipelines and preprocessing","Cross-validation and task metrics","Serialization and feature contracts"],"lab":"Train a small tabular classifier, keep a test set untouched, and compare a simple baseline against your tuned model. Save the preprocessing pipeline with the estimator.","tradeoff":"Random splits can leak future information in time-dependent data. A better validation score may not transfer to a changed production population.","url":"https://scikit-learn.org/stable/user_guide.html","licenseUrl":null},"pytorch":{"name":"PyTorch","category":"Model development","kind":"Open source","delivery":"CPU or compatible accelerator runtime","what":"A tensor and automatic-differentiation framework for deep learning. Useful when you need to understand training, custom model code, memory consumption or model execution.","learn":["Tensors, shapes and device placement","Autograd and optimization loops","Datasets and batching","Checkpoint saving and inference mode"],"lab":"Train a tiny model, reload its checkpoint in a fresh process, and compare predictions and memory usage with training mode disabled.","tradeoff":"CUDA, drivers and framework builds must be compatible. Distributed training is an additional skill, not a requirement for every AI role.","url":"https://docs.pytorch.org/tutorials/beginner/basics/intro.html","licenseUrl":null},"docker":{"name":"Docker / container images","category":"Packaging","kind":"Mixed editions","delivery":"Open-source engine components; Docker Desktop and hosted products have separate commercial terms","what":"Packages application code and its userspace dependencies into images that can be promoted between environments. Images do not include a complete independent host kernel.","learn":["Image layers and reproducible builds","Non-root users and minimal base images","Runtime secrets and health probes","Image digests, scanning and registry access"],"lab":"Containerize your evaluation API with a pinned base, a non-root user and a health check; run it without baking credentials into the image.","tradeoff":"A container alone is not a strong sandbox for arbitrary hostile agent code. Desktop licensing differs from engine licensing.","url":"https://docs.docker.com/get-started/docker-overview/","licenseUrl":null},"kubernetes":{"name":"Kubernetes","category":"Orchestration","kind":"Open source","delivery":"Self-managed clusters or paid managed services","what":"Reconciles desired workload state across a cluster. It schedules containers and exposes deployment, networking and storage primitives; an AI runtime still has to execute the model.","learn":["Pods, Deployments, Services and Jobs","Requests, limits, probes and autoscaling","RBAC, network policy and service identity","GPU resources, node selection and disruption"],"lab":"Deploy a CPU mock model service; test readiness failure, a rolling update, resource limits and access from a second namespace.","tradeoff":"Cluster complexity is unnecessary for many small API-based applications. Namespace separation alone is not a complete tenant security boundary.","url":"https://kubernetes.io/docs/concepts/overview/","licenseUrl":null},"helm":{"name":"Helm","category":"Packaging","kind":"Open source","delivery":"Kubernetes package manager","what":"Packages related Kubernetes resources as charts with configurable values. Useful for repeatable installation of serving and observability components.","learn":["Chart structure and values","Template rendering and schema checks","Release upgrades and rollback","Dependencies, hooks and version compatibility"],"lab":"Create a small chart for your service. Render it before installation and demonstrate a safe rollback after changing an image tag.","tradeoff":"A rendered manifest can still be insecure. The current charts documentation warns that parts await Helm 4 updates; use documentation matching your installed major version.","url":"https://helm.sh/docs/topics/charts/","licenseUrl":null},"opentofu":{"name":"OpenTofu","category":"Infrastructure as code","kind":"Open source","delivery":"CLI with your chosen state backend and CI","what":"Describes infrastructure resources declaratively and plans changes using provider APIs. Useful for recreating networking, compute and identity boundaries.","learn":["Providers, resources and modules","Plan/apply review","Remote state, locking and access control","Import, drift and safe resource lifecycle"],"lab":"Create an isolated lab environment, inspect the plan, simulate configuration drift and remove the lab through reviewed changes.","tradeoff":"State can contain sensitive values. Compatibility with Terraform configurations and providers must be tested for the versions you select.","url":"https://opentofu.org/docs/intro/","licenseUrl":null},"terraform":{"name":"Terraform","category":"Infrastructure as code","kind":"Source available","delivery":"CLI; commercial HCP Terraform and enterprise products available","what":"Declarative infrastructure provisioning used across clouds. Study providers, dependency graphs and state management; the transferable skill is controlled infrastructure change.","learn":["Module inputs and outputs","Plan review and policy gates","State isolation, locking and secrets","Provider version pinning and drift"],"lab":"Provision a small sandbox with a narrowly scoped identity and show how a reviewer can understand the proposed changes before apply.","tradeoff":"The current repository license is Business Source License 1.1 with an additional use grant; do not label every Terraform version as open source. Review exact version and intended use.","url":"https://developer.hashicorp.com/terraform/intro","licenseUrl":"https://github.com/hashicorp/terraform/blob/main/LICENSE"},"actions":{"name":"GitHub Actions","category":"CI/CD","kind":"Commercial service","delivery":"Hosted service; hosted or self-hosted runners","what":"Runs workflows triggered by repository events or schedules. Useful for packaging, tests, evaluations and release gates. Self-hosted runners remain part of your security boundary.","learn":["Events, jobs and reusable workflows","Artifacts and dependency caching","OIDC federation and minimum permissions","Untrusted pull requests and protected deployment environments"],"lab":"Run deterministic tests and a small evaluation dataset on a pull request; publish a report and block promotion on a documented regression.","tradeoff":"Runner source availability does not make the hosted service open source. Avoid exposing deployment credentials to untrusted workflow code.","url":"https://docs.github.com/en/actions/get-started/understand-github-actions","licenseUrl":null},"argocd":{"name":"Argo CD","category":"Continuous delivery","kind":"Open source","delivery":"Self-hosted controller; commercial managed options exist","what":"Continuously compares Kubernetes resources with a desired state stored in Git. It is the deployment reconciliation layer; build and test jobs belong in CI.","learn":["Applications and desired state","Sync policy and health assessment","Drift, rollback and pruning","Repository credentials and project boundaries"],"lab":"Deploy a service from a repository, create harmless configuration drift, inspect the difference and restore the declared state.","tradeoff":"Automatic sync and pruning can propagate a bad change. Model weights, database migrations and application quality require separate release controls.","url":"https://argo-cd.readthedocs.io/en/stable/","licenseUrl":null},"mlflow":{"name":"MLflow","category":"Lifecycle & evaluation","kind":"Open source","delivery":"Self-hosted services; managed commercial offerings are separate","what":"Tracks experiments and artifacts and supports model registry workflows. It also provides tracing and evaluation capabilities for generative applications.","learn":["Runs, parameters, metrics and artifacts","Model packaging and signatures","Version aliases, tags and promotion","Evaluation datasets and trace inspection"],"lab":"Track two experiments, register a chosen model with its input contract, and reproduce it from a clean environment before assigning an alias.","tradeoff":"A registry is not automatically an approval system. Fixed registry stages are deprecated; use versions, aliases and environment controls with access policies.","url":"https://mlflow.org/docs/latest/","licenseUrl":null},"airflow":{"name":"Apache Airflow","category":"Workflow orchestration","kind":"Open source","delivery":"Self-hosted scheduler and workers; managed services available","what":"Expresses scheduled or triggered workflows as Python DAGs. Well suited to batch ingestion, evaluation and training orchestration.","learn":["DAG dependencies and scheduling","Task retries and idempotency","Backfills, partitions and data intervals","Connections, credentials and observability"],"lab":"Build an ingestion-to-training DAG and backfill two dates. Re-run a task without creating duplicate records or replacing the wrong artifact.","tradeoff":"Do not put a latency-sensitive token-streaming request loop into a batch scheduler. Large payloads should live in storage, not task metadata.","url":"https://airflow.apache.org/docs/apache-airflow/stable/index.html","licenseUrl":null},"kubeflow":{"name":"Kubeflow components","category":"ML orchestration","kind":"Open source","delivery":"Kubernetes components installed as needed","what":"A collection of projects for ML on Kubernetes, including pipelines, training, tuning and notebooks. Choose a component to solve a real requirement.","learn":["Pipeline components and artifacts","Containerized steps and reproducibility","Training resources and quotas","Authentication and storage integration"],"lab":"Run a small pipeline that validates data, trains on CPU and emits an evaluation artifact. Record image digests and inputs.","tradeoff":"Installing the entire ecosystem brings substantial operational overhead. A managed pipeline or a simple CI job can be enough for an early project.","url":"https://www.kubeflow.org/docs/components/","licenseUrl":null},"vllm":{"name":"vLLM","category":"Inference runtime","kind":"Open source","delivery":"Self-hosted model server; hardware and model support vary","what":"Executes supported language models with serving optimizations such as batching and KV-cache management. An API-compatible endpoint does not imply identical behavior to every model provider.","learn":["Model loading and tokenizer compatibility","Prefill, decode and KV-cache pressure","Concurrency, batching and memory limits","Quantization and supported parallelism"],"lab":"Benchmark one small supported model across prompt lengths and concurrency levels. Record TTFT, output speed, errors, GPU memory and quality.","tradeoff":"Inspect model license and hardware fit separately. Higher throughput can worsen tail latency; report the workload behind every performance number.","url":"https://docs.vllm.ai/en/stable/","licenseUrl":null},"sglang":{"name":"SGLang","category":"Inference runtime","kind":"Open source","delivery":"Self-hosted serving runtime","what":"An alternative serving stack for supported language and multimodal models, with prefix reuse and scheduling optimizations. Evaluate it on the same workload as other runtimes.","learn":["Prefix caching and cache locality","Continuous request scheduling","Supported model and quantization paths","Parallel serving and memory pressure"],"lab":"Repeat the same warm and cold benchmark used for vLLM; include shared-prefix and unrelated prompts to explain cache effects.","tradeoff":"Performance comparisons are invalid when models, hardware, output lengths or quality differ. Framework support changes quickly.","url":"https://docs.sglang.io/","licenseUrl":null},"kserve":{"name":"KServe","category":"Serving orchestration","kind":"Open source","delivery":"Kubernetes serving control plane","what":"Manages model-serving deployments on Kubernetes. It coordinates serving infrastructure while an underlying runtime such as vLLM performs inference.","learn":["Serving resources and runtime selection","Autoscaling and readiness","Storage initialization and model versions","Traffic, networking and observability"],"lab":"Deploy a small model with a supported runtime, measure cold start and roll back a bad version using the selected deployment mode.","tradeoff":"Scaling features and dependencies differ by installation mode. Adding KServe does not remove the need to tune the model runtime.","url":"https://kserve.github.io/website/","licenseUrl":null},"ray":{"name":"Ray Serve","category":"Serving orchestration","kind":"Open source","delivery":"Python serving framework; self-hosted or commercial managed deployments","what":"Composes scalable Python model services and preprocessing stages. Useful when a request traverses multiple Python components or models.","learn":["Deployments and replicas","Request routing and batching","Resource requirements and autoscaling","Deployment graphs and fault handling"],"lab":"Create a preprocessing-to-model pipeline, overload it in a controlled test, and observe queueing before adding replicas.","tradeoff":"Distributed execution introduces failure and serialization boundaries. Benchmark whether a simpler single-process service is sufficient first.","url":"https://docs.ray.io/en/latest/serve/index.html","licenseUrl":null},"otel":{"name":"OpenTelemetry","category":"Observability","kind":"Open source","delivery":"SDKs, instrumentation and Collector; requires a storage/analysis backend","what":"Collects and transports traces, metrics and logs using shared conventions. It helps connect an API request with model, retrieval and tool operations.","learn":["Span context and propagation","Collector receivers, processors and exporters","Sampling, cardinality and redaction","Versioned GenAI semantic conventions"],"lab":"Trace a request through retrieval and a mock model call. Drop sensitive prompt fields and retain correlation, duration and error metadata.","tradeoff":"OpenTelemetry is not a trace database or a dashboard. Semantic conventions can change; pin instrumentation and test emitted schemas.","url":"https://opentelemetry.io/docs/what-is-opentelemetry/","licenseUrl":null},"prometheus":{"name":"Prometheus","category":"Observability","kind":"Open source","delivery":"Self-hosted time-series monitoring; managed variants available","what":"Collects time-series metrics and provides PromQL for querying them. Useful for serving queues, latency distributions and infrastructure saturation.","learn":["Counters, gauges and histograms","Scraping and service discovery","PromQL rates and histogram quantiles","Alert rules and label cardinality"],"lab":"Instrument request outcomes and latency buckets. Build an alert on sustained user-visible errors and test it with a fault injection.","tradeoff":"Do not put request IDs or raw user prompts into metric labels. Averages can hide tail latency and a healthy GPU does not prove a correct answer.","url":"https://prometheus.io/docs/introduction/overview/","licenseUrl":null},"grafana":{"name":"Grafana","category":"Observability","kind":"Open core","delivery":"Self-hosted open-source edition; commercial cloud and enterprise editions","what":"Visualizes data from metrics, logs and tracing systems. Use dashboards to answer an operational question and connect the answer to an action.","learn":["Data sources and query variables","Dashboards for service-level objectives","Alert routing and annotations","Access control and dashboard provisioning"],"lab":"Build a service dashboard showing availability, queue depth, p95 latency and cost per completed task with release annotations.","tradeoff":"Grafana core uses AGPLv3; commercial editions and plugins have separate terms. A dashboard without a runbook is weak incident preparation.","url":"https://grafana.com/docs/grafana/latest/introduction/","licenseUrl":"https://grafana.com/licensing/"},"langfuse":{"name":"Langfuse","category":"LLM observability & evaluation","kind":"Open core","delivery":"Self-hosted core or commercial cloud; enterprise features separately licensed","what":"Captures LLM application traces and links them to prompt versions, evaluation datasets and scores. Useful for investigating a quality regression.","learn":["Trace and generation structure","Prompt versioning","Dataset experiments and scoring","Retention, sensitive data and access"],"lab":"Compare two prompt versions on a labeled dataset and inspect several failures in their full retrieval and tool-call context.","tradeoff":"Core code outside designated enterprise directories is MIT licensed; enterprise features differ. Scores inherit the limitations of their grader and sample.","url":"https://langfuse.com/docs","licenseUrl":"https://github.com/langfuse/langfuse/blob/main/LICENSE"},"phoenix":{"name":"Arize Phoenix","category":"LLM observability & evaluation","kind":"Source available","delivery":"Self-hostable software; separate commercial Arize products","what":"Supports tracing, evaluation datasets and experiments for AI applications. It can help compare retrieval or prompt changes while examining individual traces.","learn":["OpenTelemetry-based traces","Dataset experiments","Response and retrieval evaluation","Permissions and data retention"],"lab":"Evaluate the same labeled examples before and after a retrieval change and link score differences to traces.","tradeoff":"The repository license is Elastic License 2.0 despite open-source wording in its README. Assess the license conditions for your deployment and use.","url":"https://github.com/Arize-ai/phoenix","licenseUrl":"https://github.com/Arize-ai/phoenix/blob/main/LICENSE"},"wandb":{"name":"Weights & Biases","category":"Lifecycle & evaluation","kind":"Commercial platform","delivery":"Hosted or contracted deployment options; SDKs have separate licenses","what":"Provides experiment tracking, artifact workflows and visualization; Weave adds tracing and evaluation for LLM applications.","learn":["Runs and artifact lineage","Experiment comparison","Evaluation and traces with Weave","Workspace access and retention"],"lab":"Compare two experiments and preserve dataset and code versions; explain how you would export evidence if moving platforms.","tradeoff":"Do not confuse an open SDK with the license of the full service. Check hosting, retention and enterprise controls for the selected plan.","url":"https://docs.coreweave.com/products/wandb","licenseUrl":null},"opa":{"name":"Open Policy Agent","category":"Authorization & policy","kind":"Open source","delivery":"Embedded library, service or policy sidecar","what":"Evaluates declarative policy written in Rego. The caller must enforce the returned decision; OPA does not magically intercept every action.","learn":["Policy inputs and decision outputs","Rego rules and unit tests","Policy distribution and versioning","Fail-closed behavior and audit evidence"],"lab":"Deny a high-impact tool call unless its tenant, action, resource and approval match. Test missing fields, spoofed identifiers and policy unavailability.","tradeoff":"Authentication, policy evaluation and enforcement are separate layers. A model instruction to obey policy is not an enforcement point.","url":"https://www.openpolicyagent.org/docs","licenseUrl":null},"pgvector":{"name":"PostgreSQL + pgvector","category":"Retrieval","kind":"Open source","delivery":"Self-hosted PostgreSQL extension; supported managed Postgres services vary","what":"Adds vector similarity search to PostgreSQL so structured data and embeddings can share a transactional store.","learn":["Embedding dimensions and distance metrics","Exact search versus HNSW/IVFFlat","Metadata filters and query plans","Index lifecycle and transactional updates"],"lab":"Store a small document corpus with tenant metadata. Compare exact search to an approximate index and test cross-tenant denial before generation.","tradeoff":"Approximate search trades recall for speed; filtering can change recall. The extension does not generate embeddings or automatically apply your authorization model.","url":"https://github.com/pgvector/pgvector","licenseUrl":null},"opensearch":{"name":"OpenSearch","category":"Retrieval","kind":"Open source","delivery":"Self-hosted engine; commercial managed services available","what":"A search and analytics engine supporting lexical and vector-based retrieval. Useful when keyword precision, filters and semantic similarity must coexist.","learn":["Mappings, analyzers and indexing","Keyword versus vector retrieval","Hybrid ranking and relevance judgments","Shards, replicas and access boundaries"],"lab":"Compare keyword, vector and hybrid retrieval on the same judged queries, including exact product codes and ambiguous language.","tradeoff":"Search relevance needs tuning and evaluation. A managed OpenSearch service is a separate commercial product with its own supported features.","url":"https://docs.opensearch.org/latest/","licenseUrl":null},"qdrant":{"name":"Qdrant","category":"Retrieval","kind":"Open source + paid service","delivery":"Self-hosted database or managed Qdrant Cloud","what":"A vector database with payload filtering and indexing controls. Useful when a dedicated retrieval service fits the workload better than adding vectors to an existing store.","learn":["Collections, points and payloads","Vector dimensions and filtering","Indexing, quantization and recall","Snapshots and capacity planning"],"lab":"Index a corpus with document version and tenant metadata; evaluate retrieval quality before and after tuning an index parameter.","tradeoff":"A vector database is only one part of RAG. You still own parsing, permission propagation, deletion and answer evaluation.","url":"https://qdrant.tech/documentation/","licenseUrl":null},"pinecone":{"name":"Pinecone","category":"Retrieval","kind":"Commercial service","delivery":"Managed search service","what":"Managed retrieval infrastructure for vector and other supported search modes. Reduces database operations while leaving data modeling and relevance decisions to you.","learn":["Index schema and namespaces","Dense/sparse search and metadata filters","Upserts, deletion and freshness","Query usage and cost attribution"],"lab":"Upload a small synthetic corpus, isolate two tenants and measure retrieval quality and query usage before comparing a local alternative.","tradeoff":"Namespaces are useful organization boundaries, but your application must enforce access. Assess deletion behavior, limits, region and cost for the selected product.","url":"https://docs.pinecone.io/guides/get-started/overview","licenseUrl":null},"langgraph":{"name":"LangGraph","category":"Agent orchestration","kind":"Open source","delivery":"Local/application runtime; commercial managed LangChain products are separate","what":"Models stateful workflows and agents as graphs, with persistence and interruption patterns. Useful when execution must pause, resume or mix deterministic steps with model decisions.","learn":["Typed state and graph transitions","Checkpointing and thread identity","Interrupts and human approval","Durable execution and side-effect boundaries"],"lab":"Build a read-only incident assistant that pauses before a simulated write. Kill and resume the process without repeating a completed side effect.","tradeoff":"Checkpointing does not provide exactly-once business actions. External effects need idempotency keys, authorization and reconciliation.","url":"https://docs.langchain.com/oss/python/langgraph/overview","licenseUrl":null},"adk":{"name":"Google Agent Development Kit","category":"Agent orchestration","kind":"Open source","delivery":"Framework; managed cloud runtime is a separate paid service","what":"Provides building blocks for model-driven agents, tools and defined workflows. Evaluate it as one framework option rather than a required dependency for all agent projects.","learn":["Agents, tools and sessions","Sequential and conditional workflows","Evaluation and traces","Deployment and state persistence"],"lab":"Implement a small triage workflow with a bounded loop, a timeout and a mocked approval-protected action. Evaluate both task outcome and tool sequence.","tradeoff":"Framework convenience does not replace action permissions or workload evaluation. The framework and managed Agent Runtime have different responsibility boundaries.","url":"https://adk.dev/","licenseUrl":null},"mcp":{"name":"Model Context Protocol","category":"Tool interoperability","kind":"Open protocol","delivery":"Client/server implementations with independent licenses","what":"Standardizes how applications discover and interact with tools and contextual resources. It connects systems; it is not the agent planner or the application authorization policy.","learn":["Client/server roles and capabilities","Tool schemas and input validation","Transport and authentication","Untrusted server output and credential scope"],"lab":"Connect a client to a read-only local tool server. Validate arguments and reject a request for a resource outside the caller's scope.","tradeoff":"A discovered tool is not automatically trustworthy. Keep approval, authorization and audit enforcement outside model-generated text.","url":"https://modelcontextprotocol.io/docs/getting-started/intro","licenseUrl":null},"gpuoperator":{"name":"NVIDIA GPU Operator","category":"GPU operations","kind":"Open source + vendor components","delivery":"Kubernetes operator managing components with their own licenses","what":"Automates NVIDIA GPU software integration on Kubernetes, including drivers, container toolkit, device plugin and monitoring components.","learn":["Supported OS/driver/runtime matrix","Device discovery and allocation","MIG and time-slicing configurations","Driver upgrades, node draining and recovery"],"lab":"On supported hardware, expose a GPU to a test pod, record the component versions, and demonstrate recovery after a controlled node drain.","tradeoff":"Managed clusters may already install some components. Avoid conflicting driver managers; GPU features and licensing depend on the hardware and component.","url":"https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/overview.html","licenseUrl":null},"dcgm":{"name":"NVIDIA DCGM / exporter","category":"GPU operations","kind":"Vendor components","delivery":"GPU telemetry libraries/tools and exporter; inspect component licenses","what":"Collects GPU health and performance information. The exporter exposes selected measurements for systems such as Prometheus.","learn":["Device health and error signals","Memory and utilization metrics","MIG-aware attribution where supported","Diagnostic limits and hardware compatibility"],"lab":"Correlate GPU memory and utilization with request queue and latency during a load test; investigate an idle GPU behind a growing queue.","tradeoff":"Not every field is supported on every GPU. High utilization alone cannot diagnose memory bandwidth, networking or application bottlenecks.","url":"https://docs.nvidia.com/datacenter/dcgm/latest/user-guide/getting-started.html","licenseUrl":null},"litellm":{"name":"LiteLLM","category":"AI gateway","kind":"Open core","delivery":"SDK or self-hosted proxy; enterprise/managed offerings separate","what":"Normalizes access to model providers and supplies routing and gateway features such as virtual keys and usage tracking.","learn":["Provider adapters and model naming","Retries, timeouts and fallbacks","Tenant keys, budgets and rate limits","Usage reconciliation and audit trails"],"lab":"Route two tenant keys to a mock provider, inject throttling, and verify bounded retries, tenant quotas and usage attribution.","tradeoff":"API compatibility does not equal model equivalence. Fallbacks can cross data boundaries or change quality; verify feature licensing and deploy a reviewed version.","url":"https://docs.litellm.ai/docs/","licenseUrl":null},"opencost":{"name":"OpenCost","category":"Cost allocation","kind":"Open source","delivery":"Self-hosted cost allocation components and billing integrations","what":"Measures and allocates Kubernetes infrastructure costs for showback and chargeback. Useful for connecting shared cluster spend with workloads.","learn":["Allocation by workload, namespace and labels","Shared and idle cost distribution","Price sources and billing reconciliation","Usage windows and reporting gaps"],"lab":"Allocate a small cluster's cost between two namespaces, explain idle capacity, and reconcile totals against an independent cost estimate.","tradeoff":"Kubernetes resource cost is not the full cost of an AI task. Add model APIs, storage, networking, evaluation and operating effort.","url":"https://opencost.io/docs/","licenseUrl":null},"backstage":{"name":"Backstage","category":"Developer portal","kind":"Open source","delivery":"Self-hosted framework; commercial managed options exist","what":"A framework for internal developer portals, including a software catalog, templates and technical documentation. It gives teams a consistent entry point to owned services.","learn":["Catalog entities and ownership","Software templates and input validation","TechDocs and documentation lifecycle","Plugin permissions and backend integrations"],"lab":"Create a catalog entry and template for an AI API that includes an owner, evaluation command, telemetry link and deployment instructions.","tradeoff":"A portal does not provision every dependency or enforce every runtime policy by itself. Review plugin access and treat template credentials as privileged.","url":"https://backstage.io/docs/overview/what-is-backstage/","licenseUrl":null}},"concepts":{"lifecycle":{"name":"Training, fine-tuning, inference and retrieval","explain":"Training learns parameters from data; fine-tuning updates a pretrained model for a narrower task. Inference runs the selected model. Retrieval supplies external context at request time without necessarily changing model parameters. The choice depends on the defect you are trying to fix.","example":"A support assistant with missing current policy documents may need retrieval. A consistent formatting failure may need better instructions, constrained output or task-specific tuning.","pitfall":"Fine-tuning is not a reliable way to keep frequently changing facts current, and retrieval cannot automatically repair weak reasoning.","lab":"Write an experiment plan comparing a prompt-only baseline with retrieval. Define the failure category before proposing fine-tuning.","refs":["foundations","rag","mlops"]},"tokens":{"name":"Tokens, context and output contracts","explain":"Tokenization converts inputs into model-specific units. Context includes instructions, history, retrieved text and tool results, and capacity must also be reserved for generation. Model output needs parsing and validation before it becomes an application action.","example":"A large conversation can exhaust a context budget even when the latest user question is short. Summarization changes the information available to later steps.","pitfall":"A large advertised context window does not establish reliable retrieval of every fact inside it. Token counts differ across tokenizers and providers.","lab":"Log input/output usage, enforce a context policy and test long histories, malformed outputs and requests close to the configured limit.","refs":["foundations","tool-vllm"]},"evaluation":{"name":"Evaluation datasets and release gates","explain":"Define what a successful outcome means, collect representative examples, separate development from held-out tests, and compare candidate changes to a baseline. Mix deterministic assertions, human judgments and model-based graders where each is appropriate.","example":"A retrieval assistant may need separate tests for document relevance, cited evidence, factual answer quality, refusal behavior and tenant isolation.","pitfall":"A single average score can hide critical failures. Model graders can be biased or inconsistent; calibrate against human-labeled examples and retain disagreements.","lab":"Build at least a small, deliberately varied labeled set; version it, report results by failure category and justify any release threshold. Sample size here is a learning choice, not statistical validation.","refs":["evals","rageval","genaiops"]},"retrieval":{"name":"RAG ingestion, freshness and deletion","explain":"A RAG pipeline parses sources, creates chunks, computes embeddings, stores searchable records, retrieves candidates and passes selected context to a generator. Every chunk needs source identity, version and permission metadata so changes can propagate.","example":"When an access policy changes, the old chunk must stop appearing even if its embedding still matches the query well.","pitfall":"Re-indexing content without removing stale records can produce contradictory answers. A citation proves provenance only when its source and quoted content are valid.","lab":"Process a versioned synthetic corpus; update one document, delete another and demonstrate that the next permitted query sees the intended evidence.","refs":["rag","acl","tool-pgvector"]},"hybrid":{"name":"Lexical search, embeddings and reranking","explain":"Lexical retrieval matches terms; embeddings represent similarity in a learned vector space. Hybrid retrieval combines candidate signals, and a reranker scores a smaller candidate set more carefully. Judge the entire retrieval pipeline on relevant queries.","example":"Exact incident IDs often favor keyword matching, while paraphrased questions may benefit from embeddings. A reranker can improve order but cannot recover a relevant document absent from candidates.","pitfall":"Embedding similarity is not factual correctness. Larger candidate sets can increase latency and distract the generator; changing embedding models normally requires a deliberate index migration.","lab":"Compare lexical, vector and hybrid recall on judged queries, then measure whether reranking improves answer quality enough to justify its latency.","refs":["rageval","tool-opensearch","tool-qdrant"]},"permissions":{"name":"Authorization-aware retrieval","explain":"Carry authenticated user and tenant context from the request into retrieval enforcement. Filter against current source permissions before any protected text reaches generation, caches, logs or tool results. Revalidate when permissions or data change.","example":"Two users ask the same question but one cannot read the finance document. Their candidate sets and any answer cache entries must respect that difference.","pitfall":"Filtering the final displayed citation is too late if the model already received the protected text. Stale ACL copies and cross-tenant cache keys can leak information.","lab":"Create two tenants and an admin-only document. Test direct queries, paraphrases, cached responses and revocation against your access policy.","refs":["acl","owasp","tool-opa"]},"versioning":{"name":"Lineage, artifacts and model promotion","explain":"Record which data snapshot, code commit, environment, parameters and evaluation produced an artifact. Promotion changes what consumers use; it should be an auditable decision with a rollback path and compatible input/output contracts.","example":"An alias can select a model version, but the application also depends on its preprocessing code, feature schema and container image.","pitfall":"Reusing a mutable file path such as latest.pkl loses reproducibility. A registry entry or alias is not proof that an approval gate ran.","lab":"Rebuild an experiment from its manifest, compare predictions, then promote and revert a version while preserving the audit record.","refs":["registry","tool-mlflow","mlops"]},"drift":{"name":"Data drift, concept drift and retraining","explain":"Data drift means input distributions change; concept drift means the relationship between inputs and targets changes. Performance degradation requires outcome evidence where available. Monitoring must account for delayed labels and different business segments.","example":"A fraud model may see a new transaction mix without losing accuracy, or lose accuracy while broad input statistics remain similar.","pitfall":"A drift alert is not a command to retrain automatically. Bad labels, a broken feature pipeline or a changed business policy may be the real cause.","lab":"Simulate a changed feature distribution and delayed labels; define who investigates and what evidence authorizes retraining or rollback.","refs":["mlops","tool-sklearn"]},"features":{"name":"Features, leakage and serving consistency","explain":"Features must be available at prediction time and transformed consistently between training and serving. Time-aware joins and split strategies prevent training from seeing information that would not have existed when a decision was made.","example":"A churn model trained with a cancellation timestamp is using the outcome as an input if that timestamp is unavailable before cancellation.","pitfall":"High offline accuracy can result from leakage rather than useful prediction. A feature store does not remove the need to design point-in-time-correct data.","lab":"Build a time-based validation split, inspect each feature's availability and test that a saved preprocessing pipeline gives the same output in serving.","refs":["mlops","tool-sklearn"]},"dag":{"name":"DAGs, retries and idempotent data work","explain":"A dependency graph expresses execution order. Schedulers may retry tasks or rerun historical intervals, so each task needs stable input identity and a deliberate policy for repeated writes. Outputs should be traceable to a logical run.","example":"An embedding task retries after a network timeout. Upserting by a stable document-version/chunk key avoids duplicating records.","pitfall":"Successful scheduling does not prove data correctness. Wall-clock timestamps used as implicit input windows can make backfills impossible to reproduce.","lab":"Backfill two partitions, interrupt a write, then rerun it. Compare record counts and hashes and document the ownership of partial outputs.","refs":["tool-airflow","tool-kubeflow"]},"serving":{"name":"Online, batch and streaming inference","explain":"Online serving answers an active request, batch inference processes a dataset, and streaming emits partial outputs. They require different deadlines, failure handling and capacity choices. Streaming improves perceived responsiveness without necessarily reducing total work.","example":"A nightly document classification job can tolerate queues and cheap batch capacity; an interactive assistant has a first-token and completion latency budget.","pitfall":"A fast first token can coexist with a very slow completion. Always state whether latency includes networking, queueing, retrieval and generation.","lab":"Measure end-to-end, first-token and completion latency separately and compare an interactive workload with a batch run of the same inputs.","refs":["tool-vllm","tool-ray"]},"kv":{"name":"Prefill, decode and KV-cache memory","explain":"For autoregressive transformers, prefill processes the input context and decode generates subsequent tokens. Attention keys and values are commonly cached to avoid recomputation. Cache memory grows with active sequences and their lengths, in addition to model weights and runtime overhead.","example":"A model fits in GPU memory when idle but fails under several long-context requests because their KV caches consume additional memory.","pitfall":"Parameter count alone is insufficient for sizing. Cache layout and size depend on architecture, precision and runtime implementation; prefix caching only helps reusable prefixes under compatible conditions.","lab":"Record a memory baseline, then increase context length and concurrent sequences independently. Explain the first observed capacity constraint.","refs":["tool-vllm","tool-sglang"]},"batching":{"name":"Batching, queueing and tail latency","explain":"Batching combines work to improve hardware efficiency, while queueing delays requests until resources are available. Continuous batching admits and completes sequences dynamically. The useful operating point depends on the workload and latency objective.","example":"Increasing concurrent requests may raise total tokens per second while p99 completion latency becomes unacceptable.","pitfall":"Do not maximize throughput in isolation. Arrival patterns, prompt lengths, output caps, warmup and rejected requests all affect the result.","lab":"Run a concurrency sweep with a fixed workload; plot throughput against p95 latency and error rate, and choose a capacity point that meets the stated objective.","refs":["tool-vllm","tool-sglang","slo"]},"quantization":{"name":"Quantization and quality-performance trade-offs","explain":"Quantization represents model weights or activations using lower precision to reduce memory or computation under supported hardware and kernels. It is a deployment choice that requires both task-quality and performance evaluation.","example":"A smaller representation may enable a model to fit on available hardware, but a specialized task can regress even when general examples look fine.","pitfall":"Lower precision is not guaranteed to make every model faster. Unsupported kernels, conversions and memory access can erase the expected benefit.","lab":"Compare two supported precisions on the same task dataset and hardware. Record quality, memory, throughput and latency with exact model/runtime revisions.","refs":["tool-vllm","tool-pytorch"]},"parallelism":{"name":"Data, tensor and pipeline parallelism","explain":"Data parallelism replicates a model across workers processing different batches. Tensor parallelism splits operations or tensors across devices; pipeline parallelism splits layers into stages. Communication overhead and memory needs determine whether additional devices help.","example":"A model too large for one accelerator may need model parallelism, while a small model might scale more simply through independent serving replicas.","pitfall":"More GPUs can increase communication time and cost without useful speedup. Distributed training and distributed inference have different synchronization patterns.","lab":"Draw device placement and communication paths; measure single-device or mocked baselines before claiming scaling improvements on real hardware.","refs":["tool-pytorch","tool-vllm"]},"gpuisolation":{"name":"GPU allocation, sharing and isolation","explain":"A scheduler resource allocation is distinct from memory capacity, execution fairness and security isolation. Time slicing shares device execution; supported MIG profiles partition resources with hardware-specific properties. Choose against actual workload isolation requirements.","example":"Two jobs may be scheduled successfully onto shared GPU access yet compete for memory or interfere with latency-sensitive work.","pitfall":"A device count is not a universal measure of usable capacity. Shared GPU options are not interchangeable, and not all GPU models support the same partitioning.","lab":"Compare allocation and failure behavior for the supported modes on available hardware; label documentation-only analysis separately from measured evidence.","refs":["sharing","k8s","tool-gpuoperator"]},"drivers":{"name":"Driver, runtime and device compatibility","explain":"The host driver, container toolkit, CUDA libraries, framework build and model runtime form a compatibility chain. Operators and managed node images automate parts of this chain, but upgrades still need validation and rollback.","example":"A container starts on CPU nodes but cannot initialize the GPU because its runtime requirements do not match the host setup.","pitfall":"Installing another driver manager on a managed cluster can conflict with the provider image. A successful device listing does not prove the model workload works.","lab":"Record a tested component matrix, execute a small tensor operation in a container and document an upgrade canary plus rollback procedure.","refs":["tool-gpuoperator","tool-dcgm"]},"networking":{"name":"Storage, interconnects and accelerator bottlenecks","explain":"GPUs depend on input data, model weight loading and cross-device communication. Storage throughput, CPU preprocessing, network topology and collective operations can limit an otherwise healthy accelerator fleet.","example":"A serving replica spends minutes loading weights while the autoscaler assumes new capacity is immediately ready; distributed workers wait on a slow peer.","pitfall":"GPU utilization alone does not identify the bottleneck. Device topology and RDMA availability vary by instance, cluster and provider configuration.","lab":"Trace cold start from scheduling through weight load and readiness; create a bottleneck table covering CPU, disk, network, GPU memory and compute.","refs":["tool-gpuoperator","tool-dcgm","tool-pytorch"]},"slo":{"name":"SLIs, SLOs and quality objectives","explain":"An SLI is a measured service behavior; an SLO specifies its desired level over a window. Define user-visible availability and latency separately from task quality. Error budgets turn reliability trade-offs into explicit release and incident decisions.","example":"A service returns HTTP 200 for every request yet retrieves no usable evidence. Transport success and answer success need separate indicators.","pitfall":"A quality score without a defined evaluator, sample and review process is not a trustworthy SLI. Multi-step dependencies can consume the same request deadline.","lab":"Write an SLO with measurement boundaries and a response policy, then simulate a timeout and a semantically wrong response.","refs":["slo","evals"]},"telemetry":{"name":"Tracing, metrics and sensitive data","explain":"Traces explain request paths; metrics summarize populations; logs preserve selected events. Connect model calls, tools and retrieval with correlation identifiers while controlling content capture, retention and access.","example":"A latency spike is traced to a slow retrieval call rather than model generation, and the operator can see the route without exposing raw documents.","pitfall":"Unlimited prompt logging creates privacy and cost problems. High-cardinality labels can overwhelm metrics storage; sampling can hide rare failures.","lab":"Instrument spans and a low-cardinality error metric. Verify propagation across one asynchronous boundary and test redaction with synthetic sensitive strings.","refs":["otel","tool-otel","tool-prometheus"]},"backpressure":{"name":"Deadlines, retry budgets and overload","explain":"Set an end-to-end deadline, divide it across dependencies and bound retries with backoff and jitter. Queue limits, admission control and load shedding prevent overload from growing without bound. Only retry operations whose repetition is safe.","example":"A provider throttles requests; retries from several layers multiply traffic and exhaust the deadline before the user receives an answer.","pitfall":"A fallback can also fail or change the answer contract. Model-provider rate limits may constrain tokens as well as requests.","lab":"Inject slow responses and throttling into a mock provider; verify bounded attempts, cancellation and a clear user-facing failure.","refs":["slo","tool-litellm","tool-ray"]},"agentstate":{"name":"Agent state, persistence and side effects","explain":"Agents combine model decisions with tools and persisted execution state. Distinguish conversation history, durable workflow checkpoints and external business effects. A checkpoint lets execution resume; it does not undo or deduplicate an external action by itself.","example":"An agent submits a ticket and crashes before recording completion. On resume it must reconcile the existing ticket rather than create another.","pitfall":"Treating every step as freely replayable can duplicate payments, tickets or infrastructure changes. State must also be scoped to the right user and tenant.","lab":"Use a mock write tool with an idempotency key; crash at each boundary and demonstrate safe replay, approval and reconciliation.","refs":["persistence","tool-langgraph"]},"tools":{"name":"Tool schemas, protocols and enforcement","explain":"A tool schema describes allowed input shape, while the execution layer validates values and authorizes the requested resource and action. Protocols such as MCP enable interoperability, but trust and business permissions still need explicit implementation.","example":"A syntactically valid request to read another tenant's ticket must be denied even though it matches the JSON schema.","pitfall":"Tool discovery, authentication and authorization solve different problems. Descriptions and tool outputs can contain hostile instructions.","lab":"Build a read-only tool and test malformed arguments, unauthorized IDs, timeouts and an output containing an instruction to reveal credentials.","refs":["mcp","owasp","tool-opa"]},"identity":{"name":"Workload identity and least privilege","explain":"Identify the human, service and delegated agent separately. Exchange short-lived credentials where supported, scope them to resources and actions, and record whose authority was used. Secrets must not become model context.","example":"An assistant can draft a change but only an explicitly authorized execution identity can apply it after an approval tied to the exact action.","pitfall":"A shared administrator key removes accountability and expands blast radius. Approval text without a bound action and enforcement point is easy to bypass.","lab":"Create a permission matrix for caller, application, model provider and tool; test each forbidden transition in a synthetic environment.","refs":["owasp","nist","tool-opa"]},"injection":{"name":"Prompt injection and untrusted content","explain":"Prompt injection occurs when attacker-controlled content influences a model to violate intended behavior. Retrieved documents, tool responses and user inputs all cross trust boundaries. Combine data minimization, constrained capabilities and deterministic enforcement.","example":"A retrieved page tells an assistant to send internal notes to an external URL. The execution layer must refuse the unauthorized action regardless of what the model proposes.","pitfall":"A stronger system prompt or content filter cannot guarantee prevention. A safe-looking answer can still hide an unauthorized tool request.","lab":"Create a small adversarial corpus; record proposed actions, enforced denials and residual failures rather than claiming universal protection.","refs":["owasp","nist"]},"supplychain":{"name":"Model, dataset and software supply chains","explain":"Models, container images, packages, prompts and datasets are artifacts with provenance and access requirements. Inspect sources, pin versions and verify the behavior of loaders and deployment steps before trusting artifacts.","example":"A model package can require custom loading code; approving its weights alone does not review the executable dependency it introduces.","pitfall":"Open weights do not imply unrestricted use or safe execution. Hashes show identity, not benign behavior; scans cannot establish all model risks.","lab":"Create a manifest of artifact digests, origins, licenses and approvals. Demonstrate how a changed dependency triggers review and a reproducible rebuild.","refs":["owasp","nist","tool-docker"]},"unitcost":{"name":"Cost per successful task","explain":"Choose a business-relevant denominator and include the resources consumed to achieve it. Total cost includes provider calls, GPU time, retrieval, storage, networking, evaluation and operations. Track quality and latency with cost.","example":"Cost per successful resolution = attributable total cost divided by correctly resolved cases, under a stated success definition and measurement period.","pitfall":"A cheaper token price can be offset by longer outputs, retries or lower task success. Never silently exclude failed requests from total cost.","lab":"Calculate cost for a fixed synthetic workload, include failed attempts and compare two routes under the same quality criteria.","refs":["finops","units"]},"allocation":{"name":"Metering, allocation and billing reconciliation","explain":"Application metering attributes usage to tenants and features; provider billing records chargeable resources and adjustments. Join them with stable identifiers and time windows, then explain shared, idle and unallocated cost explicitly.","example":"A tenant consumes part of a shared GPU pool. Reserved capacity, idle time and storage need an allocation policy beyond token counts.","pitfall":"Usage estimates are not invoices. Credits, discounts, rounding and delayed billing data can create discrepancies without an application bug.","lab":"Produce a cost report with tenant, shared, idle and unallocated buckets; reconcile totals and label estimated versus billed amounts.","refs":["finops","tool-opencost","cloud-aws-cost","cloud-gcp-billing"]},"routing":{"name":"Model routing, caching and fallback","explain":"Route requests according to capability, quality, cost, latency and policy constraints. Cache only where reuse is valid for the caller, data version and task. Fallbacks must retain required security and functional properties.","example":"A low-risk classification task can use a cheaper route if it meets the same task-quality threshold; sensitive data cannot silently fall back to an unapproved region.","pitfall":"Cache hit rate is not sufficient if cached answers are stale or cross tenant boundaries. Repeated fallback attempts can increase cost during an outage.","lab":"Test a routing matrix with synthetic data, provider failure and stale cache entries; explain why each allowed fallback remains acceptable.","refs":["tool-litellm","acl","units"]},"platform":{"name":"Platform contracts and tenant boundaries","explain":"A shared AI platform offers stable APIs, policies and operational ownership to application teams. Define the supported contract, tenant quotas, identity model, service objectives and escape hatches before assembling components.","example":"An application receives a tenant-scoped model route, usage report and documented error behavior instead of a shared cloud administrator credential.","pitfall":"Centralizing a gateway can create a failure bottleneck. Platform adoption and developer lead time matter alongside technical uptime.","lab":"Write a platform contract and onboard two mock teams with separate quotas, identities and ownership records. Test one tenant exceeding its allowance.","refs":["platform","tool-litellm","tool-kubernetes"]},"goldenpath":{"name":"Golden paths and developer experience","explain":"A golden path is a supported route from a repository to an operated service. Templates encode defaults, but documentation, upgrades, ownership and feedback make the route useful over time. Measure the developer's real task completion.","example":"A service template creates tests, evaluation hooks, telemetry and a deployment manifest, with a clear owner and an upgrade path.","pitfall":"A portal full of links is not a complete platform. Mandatory templates without versioning or escape hatches can become a maintenance burden.","lab":"Have another person follow the setup instructions from a clean environment; record blockers and improve the path before adding more templates.","refs":["platform","tool-backstage","tool-actions"]},"architecture":{"name":"Architecture decisions and responsibility boundaries","explain":"Translate a business workflow into data, control and execution paths. Compare managed and self-hosted options using explicit requirements for quality, identity, residency, latency, cost, availability and operating capacity. Record assumptions and disqualifying constraints.","example":"Managed model APIs reduce runtime operations, while self-hosting may offer more deployment control but adds hardware, patching, capacity and on-call work.","pitfall":"A product feature list is not an architecture decision. Avoid claiming services are interchangeable when model support, permissions or regional availability differ.","lab":"Write an ADR with two realistic options, one proof-of-concept result, unresolved assumptions and a measurable acceptance plan.","refs":["nist","platform","genaiops"]}},"clouds":{"aws-bedrock":{"provider":"AWS","name":"Amazon Bedrock","layer":"Managed model access","what":"Managed access to foundation models and associated application capabilities. Suitable for applications that need model APIs without operating the underlying model server.","learn":["Model access and supported regions","Invocation APIs and streaming","Quotas, guardrails and evaluation","Data handling and identity boundaries"],"lab":"Call a supported model with synthetic data, record usage and latency, and test throttling handling in your application.","own":"You own prompt/data handling, application authorization, evaluation and failure behavior. Guardrails do not prove correctness.","cost":"Model invocation, provisioned capacity where selected, and supporting services; check the chosen model and region.","url":"https://docs.aws.amazon.com/bedrock/latest/userguide/what-is-bedrock.html"},"aws-sagemaker":{"provider":"AWS","name":"Amazon SageMaker AI","layer":"ML lifecycle & hosting","what":"Managed tools for building, training and deploying ML models. SageMaker AI is the ML service within the broader Amazon SageMaker portfolio; older job descriptions may simply say SageMaker.","learn":["Training jobs and artifacts","Pipelines and model registration","Endpoint modes and scaling","Monitoring, IAM and network isolation"],"lab":"Train a small model, register its artifact and deploy a temporary endpoint. Capture predictions and remove unused compute after the lab.","own":"You own dataset correctness, model selection, container compatibility, release approval and application integration.","cost":"Training and hosting resources, storage and other selected capabilities; an idle endpoint can still incur cost.","url":"https://docs.aws.amazon.com/sagemaker/latest/dg/whatis.html"},"aws-agentcore":{"provider":"AWS","name":"Amazon Bedrock AgentCore","layer":"Agent hosting & operations","what":"Modular services for running and connecting agents, including runtime, memory and gateway capabilities. Select modules against your architecture rather than assuming every agent requires the whole platform.","learn":["Runtime and session isolation","Tool connectivity and identities","Memory and persistence boundaries","Observability and evaluation"],"lab":"Host a read-only synthetic agent and document which state and tool permissions are managed versus application-defined.","own":"You own action authorization, approval semantics, idempotency and outcome quality. A hosted runtime cannot decide your business policy.","cost":"Runtime and selected component usage plus model/tool calls; inspect component-specific charging.","url":"https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/what-is-bedrock-agentcore.html"},"aws-eks":{"provider":"AWS","name":"Amazon EKS","layer":"Managed Kubernetes","what":"Managed Kubernetes for containerized workloads, including AI services and accelerator-backed deployments. Standard and Auto Mode have different infrastructure responsibilities.","learn":["Cluster and node responsibility split","Workload identity and networking","GPU node compatibility and quotas","Disruption, upgrades and scaling"],"lab":"Deploy a CPU mock model first; produce a GPU-node design with image, driver, quota and availability assumptions before renting hardware.","own":"You own workload manifests, policies, application health and the responsibilities retained by the chosen operating mode.","cost":"Cluster/control-plane charges, compute, storage and networking; verify Auto Mode or other selected fees.","url":"https://docs.aws.amazon.com/eks/latest/userguide/what-is-eks.html"},"aws-search":{"provider":"AWS","name":"Amazon OpenSearch Service","layer":"Managed retrieval","what":"Managed OpenSearch infrastructure for search and analytics. Managed domains and other deployment options have distinct operational and feature characteristics.","learn":["Domain/index configuration","Keyword and vector retrieval","Access policy and network boundaries","Snapshots, scaling and version support"],"lab":"Index a synthetic corpus, compare retrieval strategies and test a tenant-specific access rule.","own":"You own index mappings, relevance, ingestion, permission synchronization and data deletion workflows.","cost":"Provisioned or selected deployment capacity, storage, data movement and optional features; compare at equal workload.","url":"https://docs.aws.amazon.com/opensearch-service/latest/developerguide/what-is.html"},"aws-monitor":{"provider":"AWS","name":"Amazon CloudWatch","layer":"Observability","what":"AWS monitoring services for metrics, logs, traces and application operations. Connect platform telemetry with your own user-visible service and quality indicators.","learn":["Metrics and alarms","Logs and retention","OpenTelemetry integration","Dashboards and incident correlation"],"lab":"Emit a request metric, trace a mock dependency and trigger an alarm with a controlled service fault.","own":"You own instrumentation, useful alert thresholds, redaction and incident response.","cost":"Telemetry ingestion, retention, queries and selected features; sampling and cardinality affect spend.","url":"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/WhatIsCloudWatch.html"},"aws-cost":{"provider":"AWS","name":"AWS Billing and Cost Management","layer":"Cost & allocation","what":"A suite including cost analysis, budgets and billing exports. Use provider billing evidence to reconcile application-level AI usage estimates.","learn":["Cost Explorer and exports","Allocation tags and cost categories","Budgets and anomaly review","Commitments versus actual utilization"],"lab":"Create a synthetic allocation report, then map its fields to the documented billing export and explain unallocated/shared cost.","own":"You own tenant metering, allocation rules and approval of commitments. A budget alert is not automatically a hard application spend limit.","cost":"Inspect fees for chosen reports/exports and analytics storage; billing data timing differs from real-time application metering.","url":"https://docs.aws.amazon.com/cost-management/latest/userguide/what-is-costmanagement.html"},"azure-foundry":{"provider":"Azure","name":"Microsoft Foundry","layer":"Managed model & application platform","what":"The current Foundry platform brings models, agents, tools and operational capabilities together. Earlier materials and job descriptions may call it Azure AI Foundry or Azure AI Studio.","learn":["Project/resource organization","Model deployments and API contracts","Evaluation and tracing","RBAC, network isolation and regional support"],"lab":"Evaluate two prompt variants against a small labeled set and document deployment identity, data handling and fallback rules.","own":"You own use-case suitability, input/output contracts and end-to-end authorization. Availability and preview status vary by feature.","cost":"Model and deployment charges plus the services used by the application; check current regional pricing.","url":"https://learn.microsoft.com/en-us/azure/foundry/what-is-foundry"},"azure-ml":{"provider":"Azure","name":"Azure Machine Learning","layer":"ML lifecycle & hosting","what":"Managed ML development and operations for training, pipelines and deployment. Distinguish it from managed foundation-model application development in Foundry.","learn":["Jobs, environments and data assets","Pipelines and model registration","Online/batch endpoint choices","Identity, monitoring and responsible rollout"],"lab":"Run a small training job with a reproducible environment; deploy, validate and remove a test endpoint.","own":"You own data quality, feature consistency, metric selection, model approval and configuration.","cost":"Compute, endpoints, storage and connected services; idle resources and retained artifacts matter.","url":"https://learn.microsoft.com/en-us/azure/machine-learning/overview-what-is-azure-machine-learning?view=azureml-api-2"},"azure-agents":{"provider":"Azure","name":"Microsoft Foundry Agent Service","layer":"Agent hosting & operations","what":"Managed agent capabilities spanning prompt agents and hosted custom agents, with model/tool integration and operational controls. Deployment styles have different constraints.","learn":["Prompt versus hosted agents","Runtime, conversations and toolboxes","Identity and tool permissions","Evaluation and Application Insights integration"],"lab":"Build a read-only assistant and a mocked approval step; trace a complete run and document persistence and retry behavior.","own":"You own business permissions, safe external effects and acceptance criteria. Check preview status for the exact feature.","cost":"Runtime, model calls, tool services and related resources; not a single universal per-agent price.","url":"https://learn.microsoft.com/en-us/azure/foundry/agents/overview"},"azure-search":{"provider":"Azure","name":"Azure AI Search","layer":"Managed retrieval","what":"Managed search supporting full-text, vector and hybrid retrieval. Useful as an enterprise RAG retrieval layer when its supported indexing and access patterns fit the sources.","learn":["Indexes, schemas and analyzers","Vector and hybrid queries","Ingestion and document versioning","Security filters and permission propagation"],"lab":"Compare exact-term and semantic queries, then verify that a revoked document cannot reach the answer context.","own":"You own source permission mapping, relevance evaluation, freshness and deletion assurance; search access is not the whole app policy.","cost":"Service capacity and selected capabilities, plus embedding/processing costs; inspect tier and regional support.","url":"https://learn.microsoft.com/en-us/azure/search/search-what-is-azure-search"},"azure-aks":{"provider":"Azure","name":"Azure Kubernetes Service (AKS)","layer":"Managed Kubernetes","what":"Managed Kubernetes with operating-mode choices for container platforms. Suitable for self-managed AI runtimes when the added infrastructure control is needed.","learn":["Standard versus Automatic responsibility","Node pools and GPU support","Workload identity and network controls","Upgrades, scaling and disruption"],"lab":"Deploy a CPU serving mock and write a tested rollout/rollback procedure before adding a supported GPU node pool.","own":"You own application resources and policies, plus node/runtime responsibilities specific to the mode.","cost":"Node compute, storage, networking and any selected management tiers or add-ons.","url":"https://learn.microsoft.com/en-us/azure/aks/what-is-aks"},"azure-monitor":{"provider":"Azure","name":"Azure Monitor / Application Insights","layer":"Observability","what":"Collects metrics, logs and traces; Application Insights provides application performance monitoring with OpenTelemetry integration.","learn":["Application instrumentation","Log queries and retention","Alerts and dashboards","Trace correlation across dependencies"],"lab":"Trace an API-to-model mock call, add a release annotation and demonstrate an alert with a runbook.","own":"You own content redaction, meaningful user-centric indicators, sampling and incident handling.","cost":"Ingestion, retention, queries and selected monitoring features; plan data volumes explicitly.","url":"https://learn.microsoft.com/en-us/azure/azure-monitor/fundamentals/overview"},"azure-cost":{"provider":"Azure","name":"Microsoft Cost Management","layer":"Cost & allocation","what":"Tools for analyzing, monitoring and optimizing Microsoft Cloud costs. Connect billing scopes and exports to application usage and ownership.","learn":["Billing scopes and permissions","Cost analysis and exports","Budgets and allocation labels","Forecasting and commitment review"],"lab":"Map a synthetic per-tenant AI ledger to cost analysis fields and explain how retries and shared capacity appear.","own":"You own workload metering and business allocation rules. Validate enforcement separately from notification budgets.","cost":"Export storage, analytics and related resources can cost money even where management features are included.","url":"https://learn.microsoft.com/en-us/azure/cost-management-billing/costs/overview-cost-management"},"gcp-platform":{"provider":"Google Cloud","name":"Managed AI platform / Vertex AI lineage","layer":"ML lifecycle & managed models","what":"Current documentation uses Gemini Enterprise Agent Platform; the product page also uses Gemini platform. Vertex AI remains a useful legacy search term. The platform covers ML training/deployment and generative application capabilities.","learn":["Training and prediction","Pipelines and model registry","Model access and evaluation","IAM, region and quota boundaries"],"lab":"Run one small reproducible training or model-API experiment and record the exact service/API names used in your environment.","own":"You own data, evaluation, access configuration and operational acceptance. Verify naming, supported regions and feature maturity in current docs.","cost":"Training/serving compute, model API usage, storage and connected services; compare an explicit workload.","url":"https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning"},"gcp-agents":{"provider":"Google Cloud","name":"Agent Runtime / Agent Platform","layer":"Agent hosting & operations","what":"Managed agent execution and associated session/memory capabilities within the evolving Google Cloud AI platform. Older resources may refer to Vertex AI Agent Engine.","learn":["Framework deployment paths","Runtime and session state","Memory and tool connectivity","Tracing, identities and resource limits"],"lab":"Deploy a minimal read-only agent, trace a session and document state retention and authorization around every tool.","own":"You own business actions, idempotency and evaluation. Framework support and component guarantees must be checked individually.","cost":"Runtime and selected memory/session services plus model/tool use and observability.","url":"https://docs.cloud.google.com/gemini-enterprise-agent-platform/scale"},"gcp-gke":{"provider":"Google Cloud","name":"Google Kubernetes Engine (GKE)","layer":"Managed Kubernetes","what":"Managed Kubernetes with Autopilot and Standard operating modes. Supports AI infrastructure patterns with mode- and hardware-specific constraints.","learn":["Autopilot versus Standard responsibilities","Accelerator availability and quotas","Workload identity and scheduling","Autoscaling, maintenance and disruption"],"lab":"Run a CPU service and compare the operational responsibilities of both modes for a proposed GPU workload.","own":"You own application behavior, security configuration and the responsibilities retained by the selected mode.","cost":"Compute/resource allocation, management, storage and networking; GPU capacity and pricing depend on the selected setup.","url":"https://docs.cloud.google.com/kubernetes-engine/docs/concepts/kubernetes-engine-overview"},"gcp-monitor":{"provider":"Google Cloud","name":"Cloud Monitoring","layer":"Observability","what":"Managed monitoring for Google Cloud and application metrics, dashboards and alerting. Combine it with the chosen logging and tracing services.","learn":["Metric types and collection","Dashboards and alert policies","Service monitoring and SLOs","Telemetry permissions and volume"],"lab":"Create a synthetic availability indicator and alert, then link its runbook to a trace/log investigation workflow.","own":"You own instrumentation, quality measures and actionable response policies.","cost":"Selected telemetry ingestion, retention and related services; check current pricing and quotas.","url":"https://docs.cloud.google.com/monitoring/docs/monitoring-overview"},"gcp-billing":{"provider":"Google Cloud","name":"Cloud Billing export + BigQuery","layer":"Cost & allocation","what":"Exports billing and usage data to BigQuery for detailed analysis. Enable the desired export early and inspect its schema and coverage.","learn":["Standard versus detailed exports","Projects, labels, SKUs and credits","Resource allocation and export delays","SQL reconciliation and reporting"],"lab":"Build SQL over a synthetic export to allocate AI spend by project and resource, retaining credits and unknown ownership explicitly.","own":"You own application-level tenant metering and allocation logic. Exports are not a real-time request admission controller.","cost":"BigQuery storage/query usage and related services; data completeness and timing depend on export configuration.","url":"https://docs.cloud.google.com/billing/docs/how-to/export-data-bigquery"},"oci-genai":{"provider":"Oracle Cloud","name":"OCI Generative AI","layer":"Managed model access","what":"Managed generative AI capabilities including model access and related customization/deployment options. Consider it when OCI is relevant to the employer or data platform.","learn":["Supported models and regions","Inference and embedding APIs","Dedicated versus other supported deployment options","IAM policies and data boundaries"],"lab":"Use a synthetic request to inspect response, usage and error handling; compare responsibility boundaries with a self-hosted runtime.","own":"You own task quality, application permissions and deployment suitability. Confirm exact model availability before designing around it.","cost":"Selected model/deployment usage, dedicated capacity where applicable and connected resources.","url":"https://docs.oracle.com/en-us/iaas/Content/generative-ai/overview.htm"},"oci-compute":{"provider":"Oracle Cloud","name":"OCI Compute / GPU shapes","layer":"GPU compute","what":"Virtual machines and bare-metal compute, including GPU shapes and selected cluster networking configurations. Relevant to accelerator and self-hosted serving paths.","learn":["Shape and accelerator selection","Images, drivers and storage","Network topology and quotas","Lifecycle, telemetry and recovery"],"lab":"Produce a capacity/compatibility checklist and, only with suitable hardware, validate a small model plus a recovery drill.","own":"You own the software stack and workload operations. Hardware availability, capacity limits and networking features vary by shape and region.","cost":"Instance/accelerator time, attached storage and networking; verify shutdown and termination billing behavior.","url":"https://docs.oracle.com/en-us/iaas/Content/Compute/Concepts/computeoverview.htm"},"databricks":{"provider":"Data platforms","name":"Databricks ML / AI capabilities","layer":"Managed data & ML platform","what":"An integrated commercial platform for data preparation, ML development and operations. Includes managed MLflow integration and capabilities connected to its data governance system.","learn":["Data/feature lineage and permissions","Experiments and registered models","Jobs and serving options","Governance and environment isolation"],"lab":"Train a small model from governed sample data and trace the data-to-model lineage; compare operational effort with self-hosted MLflow.","own":"You own data quality, appropriate permissions and application behavior. Platform features vary by cloud, region and edition.","cost":"Platform usage, compute, storage and serving; open-source MLflow pricing does not describe the managed platform.","url":"https://docs.databricks.com/aws/en/machine-learning/"},"snowflake":{"provider":"Data platforms","name":"Snowflake AI / Cortex capabilities","layer":"Managed data & AI platform","what":"AI and ML capabilities near Snowflake data, including Cortex functions, search and agent offerings. Useful when governed enterprise data already resides there.","learn":["Cortex functions and model access","Search and agent boundaries","Data permissions and governance","Usage attribution and feature availability"],"lab":"Prototype a retrieval or summarization workflow over synthetic tables and test which identity can access the underlying records.","own":"You own semantic correctness, source access policy and end-to-end workflow permissions. Verify each feature's availability and limits.","cost":"Feature-specific consumption and compute/storage costs; inspect the current pricing model for the exact capability.","url":"https://docs.snowflake.com/en/guides-overview-ai-features"},"gcp-rag":{"provider":"Google Cloud","name":"RAG Engine on Agent Platform","layer":"Managed retrieval pipeline","what":"Managed capabilities for bringing external data into a retrieval-augmented application. Inspect supported sources, vector stores and deployment modes for the chosen environment.","learn":["Corpus ingestion and parsing","Embedding and retrieval configuration","Metadata filtering and permissions","Index freshness and evaluation"],"lab":"Ingest a synthetic versioned corpus, compare retrieved evidence for several queries and test removal of a source document.","own":"You own source access mapping, end-to-end permissions, relevance and answer quality. Managed ingestion does not automatically establish safe authorization.","cost":"Selected ingestion, embedding, storage, retrieval and generation resources; inspect the configured backend.","url":"https://docs.cloud.google.com/gemini-enterprise-agent-platform/build/rag-engine/rag-overview"}},"paths":{"platform":{"mission":"Make AI capabilities usable by multiple teams through supported APIs, isolated access and dependable operations. Your customers are application teams; your product is their route to a safe deployment.","day":["Onboard a tenant and define its model routes, quota and owner","Investigate provider failures, latency or unusual usage across services","Review changes to platform contracts, identity and deployment automation"],"entry":"A DevOps/cloud background transfers well. Start with Linux, networking, HTTP, Python, containers and one cloud IAM model. Senior platform ownership also requires cross-team API design, migration planning and on-call judgment.","concepts":["lifecycle","platform","identity","routing","telemetry","backpressure","evaluation","unitcost"],"tools":{"Start here":["python","docker","litellm","otel"],"Compare alternatives":["opentofu","terraform"],"Add when needed":["kubernetes","helm","argocd","opa"]},"stack":"Python API → tenant identity → LiteLLM or a small routing adapter → mock/approved model provider → OpenTelemetry. Start locally with two synthetic tenants. Add Kubernetes only when you can explain its operational benefit.","managed":"Choose one managed model platform: Bedrock, Microsoft Foundry or Google Cloud AI. Keep identity, quotas, application evaluation and incident ownership explicit around that service.","clouds":["aws-bedrock","aws-eks","aws-monitor","azure-foundry","azure-aks","azure-monitor","gcp-platform","gcp-gke","gcp-monitor","oci-genai"],"queries":["AI Platform Engineer","MLOps Platform Engineer","Platform Engineer machine learning","Cloud AI Engineer"],"phases":[{"name":"Understand the platform contract","tasks":["Trace a request and its credentials end to end","List model, tool and tenant capabilities","Implement a mock endpoint with defined errors"],"artifact":"API contract, responsibility map and runnable mock","gate":"Explain which failures belong to the provider, platform and application."},{"name":"Design tenant boundaries","tasks":["Create two tenant identities and quotas","Define approved model routes and fallbacks","Design telemetry fields and retention"],"artifact":"Threat-aware architecture and policy matrix","gate":"Show that tenant A cannot use tenant B's credentials or allowance."},{"name":"Build a supported deployment","tasks":["Package the API and add automated contract tests","Instrument provider, retrieval and tool spans","Provision one isolated environment with reviewed IaC"],"artifact":"Repository, deployment instructions and test report","gate":"A clean setup can serve both tenants and reject unauthorized calls."},{"name":"Operate and improve","tasks":["Inject throttling and a slow dependency","Exercise rollback and quota enforcement","Reconcile usage and collect developer feedback"],"artifact":"Runbooks, cost ledger and incident report","gate":"Show bounded retries, stable tenant isolation and documented recovery limits."}],"interview":[{"question":"How would you prevent one team from exhausting shared capacity?","lookFor":"Identity-scoped quotas, admission control, fair scheduling, usage visibility and explicit isolation limits."},{"question":"When would you choose managed model APIs over self-hosting?","lookFor":"Workload quality and constraints first, then operating capacity, hardware needs, total cost and provider dependence."},{"question":"How do you measure whether the platform is useful?","lookFor":"Onboarding completion, developer lead time, supported workload success, incidents and cost—not only cluster uptime."}],"resume":"Built a two-tenant AI API lab with scoped routing, quota tests and traced failure handling; report measured workload and remaining production gaps."},"llmops":{"mission":"Make changes to prompts, models, retrieval and tools testable and releasable. The central responsibility is preserving useful application behavior as the underlying system evolves.","day":["Inspect failures and expand representative evaluation cases","Compare a candidate prompt/model with the released baseline","Run release gates and investigate post-release quality changes"],"entry":"Learn Python, APIs, Git, tests and basic statistics for interpreting evaluation results. You do not need to train a foundation model. Senior work includes experiment design, stakeholder acceptance and release-risk decisions.","concepts":["lifecycle","tokens","evaluation","versioning","telemetry","routing","backpressure","injection"],"tools":{"Start here":["python","actions","mlflow","otel"],"Compare alternatives":["langfuse","phoenix","wandb"],"Add when needed":["litellm","docker","langgraph"]},"stack":"Python evaluation harness + versioned dataset + MLflow or Langfuse + CI reports. Use a mock or one approved model API and build deterministic checks before introducing model-based graders.","managed":"Use Foundry evaluation/operations, Google Cloud model evaluation or Bedrock-related evaluation capabilities where supported. Keep an exportable dataset and independently defined acceptance criteria.","clouds":["aws-bedrock","aws-monitor","azure-foundry","azure-monitor","gcp-platform","gcp-monitor","databricks"],"queries":["LLMOps Engineer","GenAIOps Engineer","Generative AI Engineer evaluation","AI Evaluation Engineer"],"phases":[{"name":"Define success and a baseline","tasks":["Choose one bounded application task","Label normal, ambiguous and critical failure cases","Create deterministic schema and policy checks"],"artifact":"Dataset card, scoring rubric and baseline report","gate":"Explain what the score measures and which failures it misses."},{"name":"Map the change surface","tasks":["Version prompt, model, retrieval and tool configuration","Separate development from held-out cases","Specify rollout and rollback criteria"],"artifact":"Change manifest and evaluation plan","gate":"Reproduce a run and identify every changed input."},{"name":"Automate comparison","tasks":["Run candidate and baseline over the same cases","Inspect disagreements between human and model graders","Publish a CI report with category-level failures"],"artifact":"Evaluation pipeline and comparison report","gate":"A deliberately bad change is detected without hiding severe failures in an average."},{"name":"Close the feedback loop","tasks":["Collect privacy-aware production-like traces","Sample and label new failure modes","Test rollback and monitor regression after release"],"artifact":"Release record, review process and rollback drill","gate":"Explain sampling limits, grader uncertainty and the owner of release approval."}],"interview":[{"question":"How do you evaluate a nondeterministic system?","lookFor":"Representative versioned data, repeated trials where useful, task-specific checks, calibrated graders and uncertainty."},{"question":"A new model improves average score but fails an important slice. Ship it?","lookFor":"Discuss criticality, sample evidence, slice-specific gates and mitigations; an average alone cannot authorize release."},{"question":"How do you diagnose a RAG quality regression?","lookFor":"Separate retrieval, context assembly, model generation, prompt changes and evaluator changes using traces and controlled tests."}],"resume":"Implemented a versioned evaluation and release-gate lab; include dataset scope, baseline comparison, grader limitations and an example regression caught."},"mlops":{"mission":"Turn model development into a reproducible and governed lifecycle from data to training, deployment, monitoring and retraining. Conventional predictive ML remains an important part of this path.","day":["Debug a pipeline or data-quality issue","Review experiment lineage and model promotion","Investigate serving consistency, drift or delayed-label performance"],"entry":"Build Python/SQL fluency, basic probability and statistics, supervised learning concepts and reproducible software environments. DevOps skills help, but cannot substitute for understanding leakage and validation.","concepts":["lifecycle","features","versioning","dag","drift","evaluation","serving","identity"],"tools":{"Start here":["python","sklearn","mlflow","docker"],"Compare alternatives":["airflow","kubeflow","wandb"],"Add when needed":["pytorch","kubernetes","kserve"]},"stack":"A scikit-learn pipeline + MLflow + a small containerized prediction service. Add Airflow for real scheduling/backfill needs; use Kubeflow only if Kubernetes-native ML orchestration is justified.","managed":"Choose SageMaker AI, Azure ML, Google Cloud managed ML or Databricks. Learn the same artifact, lineage and promotion concepts rather than trying all platforms simultaneously.","clouds":["aws-sagemaker","azure-ml","gcp-platform","databricks","aws-monitor","azure-monitor","gcp-monitor"],"queries":["MLOps Engineer","Machine Learning Platform Engineer","ML Infrastructure Engineer","Machine Learning Engineer deployment"],"phases":[{"name":"Build a trustworthy baseline","tasks":["Use a small public or synthetic tabular task","Choose leakage-safe splits and task metrics","Save preprocessing with the model"],"artifact":"Dataset card and baseline model report","gate":"Explain why every input feature would exist at prediction time."},{"name":"Map data to prediction","tasks":["Version data, code, environment and artifacts","Design retriable pipeline steps","Define feature/input and prediction contracts"],"artifact":"Lineage manifest and lifecycle diagram","gate":"Reproduce predictions in a clean environment and trace them to inputs."},{"name":"Automate training and delivery","tasks":["Run validation, training and evaluation in a pipeline","Register a candidate and apply a promotion gate","Deploy and test compatible online or batch inference"],"artifact":"Pipeline, registry evidence and serving tests","gate":"A bad schema or metric regression blocks promotion and a previous version can be restored."},{"name":"Monitor and retrain deliberately","tasks":["Simulate data drift and delayed labels","Distinguish pipeline faults from model degradation","Exercise a reviewed retraining and rollback decision"],"artifact":"Monitoring report and retraining runbook","gate":"Justify when to retrain, when to fix data and when to leave the model unchanged."}],"interview":[{"question":"Why can high validation accuracy be misleading?","lookFor":"Leakage, wrong split strategy, class imbalance, changing population and a metric detached from business cost."},{"question":"What belongs in a model release artifact?","lookFor":"Weights/estimator, preprocessing, schema, environment, lineage, evaluation evidence and versioned serving configuration."},{"question":"Does data drift always require retraining?","lookFor":"No; investigate performance, label quality, upstream changes and business assumptions before choosing a response."}],"resume":"Built a reproducible training-to-serving pipeline with leakage checks, artifact lineage, promotion gates and a simulated drift investigation."},"inference":{"mission":"Operate model execution under explicit quality, latency, throughput and cost constraints. This path combines backend engineering with hardware-aware performance analysis.","day":["Profile prefill, decode, queueing and memory pressure","Benchmark a runtime/model change on a controlled workload","Tune deployment capacity and respond to serving failures"],"entry":"Learn Python, Linux, networking, containers, profiling and basic transformer execution. Real accelerator experience matters for performance claims. Begin with a CPU mock for orchestration, then use compatible hardware for measured serving results.","concepts":["tokens","serving","kv","batching","quantization","parallelism","backpressure","telemetry","unitcost"],"tools":{"Start here":["python","vllm","prometheus","docker"],"Compare alternatives":["sglang","ray"],"Add when needed":["kserve","kubernetes","dcgm","pytorch"]},"stack":"One supported model + vLLM + a repeatable load harness + Prometheus/DCGM. Compare SGLang using identical hardware and inputs. Add KServe or Ray only for a specific deployment/composition requirement.","managed":"Managed endpoints in SageMaker AI, Azure ML or Google Cloud reduce serving operations; EKS/AKS/GKE or OCI GPU compute provide more runtime control. Compare the boundary you actually need to own.","clouds":["aws-sagemaker","aws-eks","azure-ml","azure-aks","gcp-platform","gcp-gke","oci-compute"],"queries":["Inference Engineer","Model Serving Engineer","ML Systems Engineer","LLM Performance Engineer"],"phases":[{"name":"Understand one request","tasks":["Explain tokenizer, prefill, decode and output limits","Separate network, queue and execution timing","Record model/runtime/license/hardware requirements"],"artifact":"Serving request diagram and compatibility manifest","gate":"Explain why model weights fitting in memory does not prove concurrent serving capacity."},{"name":"Design the benchmark","tasks":["Fix input/output distributions and arrival patterns","Define latency and quality objectives","Plan warm/cold and failure measurements"],"artifact":"Versioned workload and measurement methodology","gate":"Another engineer can repeat the experiment and understand every reported metric."},{"name":"Serve and measure","tasks":["Deploy one supported runtime and model","Sweep concurrency and context length","Compare one tuning change while retaining quality tests"],"artifact":"Benchmark results, configuration and plots","gate":"Find the first bottleneck and justify a safe operating point."},{"name":"Operate under failure","tasks":["Test timeout, overload and replica restart","Validate readiness and model-load behavior","Document capacity, rollout and rollback limits"],"artifact":"Runbook, failure results and capacity model","gate":"Show bounded queues and recovery behavior without overstating tested scale."}],"interview":[{"question":"Why did throughput improve while users saw slower answers?","lookFor":"Queueing and batching trade-offs, longer output distributions, tail percentiles and measurement boundaries."},{"question":"How would you investigate GPU out-of-memory under load?","lookFor":"Weights, KV cache, context/concurrency, runtime overhead, fragmentation and supported precision controls."},{"question":"When should you use replicas versus tensor parallelism?","lookFor":"Model fit, independent request concurrency, communication overhead and hardware topology backed by measurements."}],"resume":"Benchmarked a named model/runtime on specified hardware across context and concurrency; report quality, tail latency, throughput and errors, including failed configurations."},"gpu":{"mission":"Keep accelerator capacity allocatable, compatible, observable and recoverable. Your work enables training and serving teams, while their model behavior remains a separate responsibility.","day":["Investigate Pending pods, device discovery or driver failures","Plan node maintenance and accelerator capacity","Correlate GPU health with storage, network and workload behavior"],"entry":"Build strong Linux, Kubernetes, networking and storage skills. Add CUDA/runtime literacy and distributed-system troubleshooting. Hardware-dependent skills cannot be demonstrated solely with a laptop simulation.","concepts":["drivers","gpuisolation","kv","parallelism","networking","telemetry","batching","allocation"],"tools":{"Start here":["kubernetes","gpuoperator","dcgm","prometheus"],"Compare alternatives":["opentofu","terraform"],"Add when needed":["helm","pytorch","vllm","opencost"]},"stack":"Supported GPU host or node pool + validated driver/runtime stack + GPU Operator where appropriate + DCGM/Prometheus. A CPU-only cluster is useful for scheduling concepts but cannot validate GPU isolation or performance.","managed":"Choose a supported accelerator setup on EKS, AKS, GKE or OCI Compute. Managed cluster and node modes determine which driver, image and maintenance responsibilities remain yours.","clouds":["aws-eks","azure-aks","gcp-gke","oci-compute","aws-monitor","azure-monitor","gcp-monitor"],"queries":["GPU Infrastructure Engineer","GPU Platform Engineer","HPC Engineer AI","Kubernetes GPU Engineer"],"phases":[{"name":"Map the compatibility chain","tasks":["Identify host driver, toolkit and framework versions","Distinguish scheduler allocation from runtime memory","Read the hardware-specific sharing limits"],"artifact":"Compatibility matrix and failure taxonomy","gate":"Explain a Pending pod separately from an inference OOM."},{"name":"Design placement and recovery","tasks":["Map GPU memory, topology and network needs","Choose dedicated or supported shared allocation","Plan node-drain and upgrade procedures"],"artifact":"Placement design and maintenance plan","gate":"State the tested isolation and recovery guarantees without assuming all GPU models behave alike."},{"name":"Validate on hardware","tasks":["Expose a device to a controlled workload","Collect GPU and application metrics","Test representative allocation and memory cases"],"artifact":"Hardware lab report with versions and telemetry","gate":"A workload runs reliably and measurements distinguish device, runtime and application failures."},{"name":"Operate the fleet","tasks":["Canary a compatible stack change","Exercise node loss or controlled drain","Attribute capacity, idle resources and unresolved risks"],"artifact":"Upgrade/rollback runbook and capacity report","gate":"Demonstrate recovery on tested hardware; mark multi-node or unsupported cases as unverified."}],"interview":[{"question":"How do MIG and time slicing differ?","lookFor":"Hardware-dependent partitioning versus shared execution, with explicit memory, fault-isolation and scheduling limits."},{"question":"GPUs are underutilized but a job is slow. What do you inspect?","lookFor":"Input pipeline, CPU, disk, network/collectives, synchronization and model execution rather than utilization alone."},{"question":"How do you upgrade drivers without disrupting every team?","lookFor":"Compatibility testing, canaries, drain/checkpoint behavior, capacity reserve, rollback and communication."}],"resume":"Validated a documented GPU software stack and controlled maintenance drill on specified hardware; include telemetry and distinguish simulated from measured results."},"agent":{"mission":"Build agent execution that can use tools, preserve state and recover safely. Focus on predictable boundaries around a model's decisions and externally visible actions.","day":["Debug a failed or looping agent run","Review tool schemas, permissions and persistence","Test approval, replay and outcome evaluation"],"entry":"Learn backend APIs, Python, state machines, databases, authentication and distributed side effects. A simple deterministic workflow is a useful baseline; only add model-directed decisions where they improve the task.","concepts":["lifecycle","agentstate","tools","identity","injection","backpressure","evaluation","telemetry"],"tools":{"Start here":["python","langgraph","mcp","opa"],"Compare alternatives":["adk"],"Add when needed":["otel","langfuse","litellm","docker"]},"stack":"Python + one stateful workflow framework + a durable store + a read-only MCP tool + deterministic authorization. Keep write actions mocked until approvals and idempotency are tested.","managed":"Compare AgentCore, Foundry Agent Service and Google Cloud Agent Runtime for hosting and state features. Keep the business action policy and evaluation independent of the provider.","clouds":["aws-agentcore","aws-bedrock","azure-agents","azure-foundry","gcp-agents","gcp-platform"],"queries":["Agent Platform Engineer","AI Agent Engineer","Agentic AI Engineer","Backend Engineer AI agents"],"phases":[{"name":"Choose the right execution model","tasks":["Implement a deterministic task baseline","Identify where a model decision adds value","Define success, stop conditions and allowed tools"],"artifact":"Workflow diagram and baseline results","gate":"Explain why an agent is needed, or conclude that a workflow is sufficient."},{"name":"Design state and authority","tasks":["Separate user, tenant and execution identities","Define checkpoint and external side-effect boundaries","Bind approval to an exact proposed action"],"artifact":"State machine and permission matrix","gate":"Every side effect has an owner, authorization check and replay policy."},{"name":"Build durable execution","tasks":["Implement one bounded agent loop and read-only tool","Add persistent state and a mocked write tool","Trace model, policy and tool decisions"],"artifact":"Runnable service and integration tests","gate":"Malformed, unauthorized and repeated actions are rejected or safely reconciled."},{"name":"Test recovery and abuse","tasks":["Crash before/after a tool effect","Inject hostile tool content and slow dependencies","Evaluate task success, harmful actions and cost"],"artifact":"Replay report, evaluation set and operational runbook","gate":"Resume safely with bounded work and explain residual failure modes."}],"interview":[{"question":"What happens if an agent crashes after writing to an external service?","lookFor":"Idempotency keys, durable action records, reconciliation and the distinction between checkpoint replay and exactly-once effects."},{"question":"Does MCP make tool use safe?","lookFor":"It provides interoperability; authentication, authorization, schema validation and action policy still need enforcement."},{"question":"How do you detect an agent that is looping?","lookFor":"Step/time/token budgets, repeated-state detection, tool-call tracing and task-outcome evaluation."}],"resume":"Built a stateful agent lab with scoped tools, approval-bound mock writes and crash/replay tests; report task success and denied-action evidence."},"sre":{"mission":"Keep AI services useful and available under normal load, dependency failures and behavior changes. Reliability includes service health and an explicit, carefully measured view of task quality.","day":["Investigate traces, saturation and error-budget consumption","Improve alerts, runbooks and rollback practices","Coordinate incident response across model, retrieval and application owners"],"entry":"Existing SRE skills transfer strongly. Add model-serving metrics, evaluation limitations, provider quotas and agent/retrieval failure modes. Senior work includes reliability policy and cross-team incident leadership.","concepts":["slo","telemetry","backpressure","serving","batching","evaluation","routing","agentstate"],"tools":{"Start here":["otel","prometheus","grafana","python"],"Compare alternatives":["langfuse","phoenix"],"Add when needed":["kubernetes","dcgm","litellm"]},"stack":"Instrumented mock AI service + OpenTelemetry + Prometheus/Grafana + a small quality test set. Start by detecting a real failure, then add infrastructure-specific telemetry.","managed":"Use CloudWatch, Azure Monitor/Application Insights or Google Cloud Monitoring with the selected model/agent platform. Check which signals are automatic and which your application must emit.","clouds":["aws-monitor","aws-bedrock","azure-monitor","azure-foundry","gcp-monitor","gcp-platform"],"queries":["AI SRE","Site Reliability Engineer machine learning","ML Platform SRE","Production Engineer AI"],"phases":[{"name":"Define reliability for the user","tasks":["Map a request and its dependencies","Define availability, latency and quality indicators","Document evaluator and sampling limits"],"artifact":"SLI/SLO specification with owners","gate":"Explain why HTTP success is insufficient without turning a noisy quality metric into a false guarantee."},{"name":"Design fault containment","tasks":["Allocate deadlines and retry budgets","Define overload, fallback and cancellation behavior","Map dashboards to runbook actions"],"artifact":"Failure matrix and incident playbook","gate":"Predict the blast radius of a slow provider and an unavailable retrieval store."},{"name":"Instrument and test","tasks":["Add traces and bounded-cardinality metrics","Inject timeout, throttle and malformed-output failures","Build actionable alerts and a deployment annotation"],"artifact":"Observability stack and fault-test evidence","gate":"An operator can detect, locate and explain each injected failure."},{"name":"Practise response and learning","tasks":["Run a timed incident exercise","Rollback a candidate and verify recovery","Write a postmortem and capacity follow-up"],"artifact":"Incident timeline, recovery evidence and reliability backlog","gate":"Separate observed recovery time from untested recovery promises."}],"interview":[{"question":"What SLO would you set for an AI assistant?","lookFor":"A scoped user journey, latency/availability boundaries, a defensible quality measurement and a response policy."},{"question":"Why can retries make an outage worse?","lookFor":"Amplification across layers, resource contention, deadline exhaustion and non-idempotent effects."},{"question":"How do you debug poor answers with healthy infrastructure?","lookFor":"Quality samples and traces separating retrieval, prompt, model, tool and data changes."}],"resume":"Instrumented an AI service lab and ran controlled incidents; show detection, diagnosis and recovery evidence with workload and quality-measurement limits."},"security":{"mission":"Protect the data, identities, model artifacts and actions that make up an AI system. Use threat models and enforceable controls, then demonstrate their limits with tests.","day":["Review data flows, tools and identity delegation","Test injection, access-control and output-handling failures","Improve artifact provenance, audit evidence and incident response"],"entry":"Start with application/cloud security, HTTP, IAM, secrets, threat modeling and Python testing. Add model-mediated trust boundaries and evaluation. Legal compliance and organizational risk acceptance require appropriate owners beyond an engineering lab.","concepts":["identity","injection","permissions","tools","supplychain","agentstate","telemetry","evaluation"],"tools":{"Start here":["python","opa","docker","mcp"],"Compare alternatives":["opentofu","terraform"],"Add when needed":["otel","langgraph","kubernetes","actions"]},"stack":"A synthetic RAG/tool application + deterministic authorization + an adversarial test corpus + redacted audit logs. Keep targets isolated and actions mocked or explicitly test-scoped.","managed":"Study the identity, network, logging and data-handling controls of one chosen AI platform. Foundry, Bedrock/AgentCore and Google Cloud provide different controls; validate enforcement rather than assuming feature-name equivalence.","clouds":["aws-bedrock","aws-agentcore","aws-monitor","azure-foundry","azure-agents","azure-search","azure-monitor","gcp-platform","gcp-agents","gcp-monitor"],"queries":["AI Security Engineer","GenAI Security Engineer","Product Security Engineer AI","Cloud Security Engineer machine learning"],"phases":[{"name":"Model the threats","tasks":["Inventory inputs, tools, data and artifacts","Draw trust and identity boundaries","Prioritize concrete misuse and failure scenarios"],"artifact":"Threat model with assets and owners","gate":"Distinguish malicious instructions, unauthorized data access and unsafe external effects."},{"name":"Design enforceable controls","tasks":["Define least-privilege tool permissions","Bind approvals to exact actions","Design source-permission propagation and audit retention"],"artifact":"Control matrix linked to threat scenarios","gate":"Every important control has a deterministic enforcement point and a test."},{"name":"Build and test defenses","tasks":["Implement schema and resource authorization checks","Test hostile retrieved/tool content","Validate secrets, dependency provenance and log redaction"],"artifact":"Security test suite and artifact manifest","gate":"Show what is blocked, what is detected and what remains possible."},{"name":"Operationalize risk handling","tasks":["Exercise credential revocation and containment","Retest after model/tool/configuration changes","Assign residual risks and response owners"],"artifact":"Risk register, regression results and response runbook","gate":"Avoid claiming universal prompt-injection prevention or compliance certification."}],"interview":[{"question":"Can a system prompt stop prompt injection?","lookFor":"It can guide behavior but is not a security boundary; discuss constrained capabilities, independent authorization and residual risk."},{"question":"How do you stop a RAG system leaking another tenant's data?","lookFor":"Authenticated context, retrieval enforcement, permission freshness, cache isolation, logs and adversarial tests."},{"question":"What is different about an agent service account?","lookFor":"Delegated authority, scoped tools, approval binding, short-lived credentials and accountability for external effects."}],"resume":"Threat-modeled a synthetic AI workflow and implemented authorization, revocation and adversarial regression tests; report residual risks and tested scope."},"rag":{"mission":"Make enterprise knowledge retrievable, current and permission-correct. Own the data pipeline and retrieval quality that an answer-generating application depends on.","day":["Debug parsing, indexing or freshness failures","Evaluate query relevance and retrieval changes","Verify deletion and permission revocation across indexes and caches"],"entry":"Learn Python, SQL, data pipelines, information retrieval basics and access-control modeling. Embeddings are useful, but lexical search, metadata and data quality remain essential.","concepts":["retrieval","hybrid","permissions","dag","evaluation","tokens","versioning","identity"],"tools":{"Start here":["python","pgvector","mlflow"],"Compare alternatives":["opensearch","qdrant","pinecone"],"Add when needed":["airflow","langfuse","docker"]},"stack":"Synthetic document corpus + Python ingestion + PostgreSQL/pgvector + a lexical baseline + a judged query set. Choose one vector/search backend and evaluate alternatives on the same evidence.","managed":"Compare Azure AI Search, Amazon OpenSearch Service and Google Cloud RAG Engine for your ingestion and retrieval needs. Databricks/Snowflake may fit an existing governed data estate.","clouds":["aws-search","aws-bedrock","azure-search","azure-foundry","gcp-rag","gcp-platform","databricks","snowflake"],"queries":["RAG Engineer","AI Data Engineer","Search Engineer vector","Retrieval Engineer"],"phases":[{"name":"Understand sources and questions","tasks":["Inventory document formats and permissions","Build judged queries including exact IDs and paraphrases","Define freshness, deletion and answer-quality requirements"],"artifact":"Corpus/data card and relevance judgments","gate":"Explain how document quality and permissions influence the intended answers."},{"name":"Design ingestion and retrieval","tasks":["Choose chunk boundaries and version keys","Design embedding/index migration and retries","Compare lexical, vector and hybrid candidate selection"],"artifact":"Pipeline diagram and index schema","gate":"A document can be updated, revoked and removed without orphaned searchable chunks."},{"name":"Build and evaluate","tasks":["Ingest a synthetic multi-tenant corpus","Measure retrieval before generation quality","Compare one chunking/ranking change at a time"],"artifact":"Runnable pipeline and evaluation report","gate":"Show relevant evidence retrieval and zero unauthorized context in the defined access tests."},{"name":"Operate freshness and access","tasks":["Simulate source changes and permission revocation","Test stale caches and index rebuild rollback","Measure latency, cost and unresolved retrieval failures"],"artifact":"Freshness/deletion tests and operations runbook","gate":"Report observed propagation delays and retained failure cases instead of claiming perfect RAG."}],"interview":[{"question":"When is keyword search better than vector search?","lookFor":"Exact identifiers, rare terms and lexical precision; compare on judged workload rather than choosing by trend."},{"question":"How do you evaluate RAG?","lookFor":"Retrieval relevance/recall, context quality, answer correctness/groundedness, latency, access and freshness separately."},{"question":"How do you change embedding models safely?","lookFor":"Versioned embeddings/indexes, compatible dimensions, backfill, side-by-side evaluation, cutover and rollback."}],"resume":"Built a versioned multi-tenant retrieval lab; show lexical/vector comparisons, judged queries and measured update, deletion and revocation behavior."},"finops":{"mission":"Make AI spending understandable and tied to useful outcomes. Combine usage attribution, billing reconciliation and capacity analysis with quality and latency constraints.","day":["Investigate spend changes and unallocated usage","Compare model routes or capacity options","Explain cost-quality trade-offs to engineering and business owners"],"entry":"Learn cloud billing, SQL/Python analysis, tagging and allocation, plus inference workload metrics. FinOps work is collaborative; the most useful skills include explaining assumptions and checking total cost, not just optimizing token prices.","concepts":["unitcost","allocation","routing","batching","kv","serving","platform","evaluation"],"tools":{"Start here":["python","opencost","prometheus","grafana"],"Compare alternatives":["litellm"],"Add when needed":["vllm","dcgm","otel"]},"stack":"Synthetic request ledger + Python/SQL analysis + a dashboard with a documented success denominator. Add OpenCost for Kubernetes allocation and gateway metering for model APIs.","managed":"Learn AWS Billing/Cost Management, Microsoft Cost Management or Cloud Billing exports to BigQuery alongside the AI services being billed. Choose one provider to reconcile end to end first.","clouds":["aws-cost","aws-bedrock","aws-sagemaker","azure-cost","azure-foundry","azure-ml","gcp-billing","gcp-platform","oci-compute"],"queries":["FinOps Engineer AI","Cloud Cost Engineer GPU","AI Capacity Engineer","FinOps Analyst machine learning"],"phases":[{"name":"Define the cost boundary","tasks":["Choose a task-success denominator","List model, GPU, retrieval, storage and operations cost","Separate estimated, billed and allocated values"],"artifact":"Cost model and assumptions sheet","gate":"Explain why cost per token may conflict with cost per successful task."},{"name":"Design attribution","tasks":["Assign tenant, feature, model and version identifiers","Define shared/idle allocation rules","Map application events to billing dimensions"],"artifact":"Usage schema and allocation policy","gate":"Account for retries, failures and unknown ownership without dropping their cost."},{"name":"Build a reconciled report","tasks":["Generate or ingest a usage ledger","Join billing-like data and reconcile totals","Compare two routes under the same quality objective"],"artifact":"Reproducible report and cost-quality comparison","gate":"Every discrepancy is quantified or explicitly marked unresolved."},{"name":"Choose an operating policy","tasks":["Model demand and capacity scenarios","Test budget alerts and request-level limits separately","Document a recommendation with sensitivity analysis"],"artifact":"Capacity plan and optimization decision record","gate":"Do not recommend long commitments from a tiny or unrepresentative benchmark."}],"interview":[{"question":"Why did cost rise when request volume stayed flat?","lookFor":"Longer contexts/outputs, retries, route changes, lower cache reuse, idle capacity, pricing or attribution changes."},{"question":"How do you allocate shared GPU cost?","lookFor":"A documented policy including workload use, reserved/idle capacity, platform overhead and reconciliation."},{"question":"How do you prove an optimization helped?","lookFor":"Comparable workload, quality/latency guardrails, complete cost boundary and an honest sensitivity analysis."}],"resume":"Created a reproducible AI cost-allocation report with reconciliation and cost-per-success comparisons; label synthetic data and state pricing assumptions."},"devplatform":{"mission":"Make it straightforward for developers to create, test and operate AI applications using supported templates and services. Treat the developer journey as a product with measurable outcomes.","day":["Improve templates, docs and onboarding based on user feedback","Maintain service ownership and supported deployment paths","Upgrade evaluation, identity and telemetry defaults"],"entry":"Learn application delivery, CI/CD, API design, documentation and platform operations. Senior work includes product discovery, compatibility management and facilitating adoption across teams.","concepts":["goldenpath","platform","versioning","evaluation","identity","telemetry","supplychain","architecture"],"tools":{"Start here":["backstage","actions","python","docker"],"Compare alternatives":["opentofu","terraform"],"Add when needed":["argocd","kubernetes","helm","otel"]},"stack":"A small repository template + CI/evaluation command + service ownership file + docs. Add Backstage when catalog and discovery needs justify a portal, and use GitOps when managing Kubernetes deployments.","managed":"Connect the developer path to one approved managed model platform and one deployment environment. The portal should expose supported choices and ownership, not every cloud product.","clouds":["aws-bedrock","aws-eks","azure-foundry","azure-aks","gcp-platform","gcp-gke","databricks"],"queries":["AI Developer Platform Engineer","Developer Experience Engineer AI","Internal Developer Platform Engineer","Platform Engineer GenAI"],"phases":[{"name":"Discover the developer task","tasks":["Observe or simulate a clean onboarding journey","Identify repeated setup errors and missing ownership","Define the smallest supported AI application"],"artifact":"Journey map and measurable success criteria","gate":"Explain the user problem before proposing a portal or template framework."},{"name":"Design the golden path","tasks":["Specify service contract and permitted extension points","Include identity, evaluation and telemetry defaults","Plan template versioning and upgrades"],"artifact":"Template specification and responsibility map","gate":"A generated service has an owner and a path to future updates."},{"name":"Build a usable vertical slice","tasks":["Generate a service repository with tests and docs","Run CI and a mock model evaluation","Register it in a minimal catalog or Backstage"],"artifact":"Template, example service and onboarding guide","gate":"Another person can complete the journey from a clean environment."},{"name":"Maintain and improve","tasks":["Measure onboarding outcomes and collect blockers","Upgrade a template without breaking existing users","Test rollback and publish support expectations"],"artifact":"Usability notes, migration guide and support runbook","gate":"Show measured developer outcomes and the cost of maintaining the path."}],"interview":[{"question":"How is a developer portal different from a platform?","lookFor":"The portal is an entry point; supported capabilities, policies, ownership and operational services make the platform."},{"question":"How do you stop golden paths becoming stale?","lookFor":"Versioned templates, automated checks, migration support, ownership and user feedback."},{"question":"What would you measure after launch?","lookFor":"Task completion, lead time, setup failures, adoption of supported controls and support effort."}],"resume":"Built and tested an AI service golden path with evaluation, identity and telemetry defaults; document clean-environment onboarding results and upgrade behavior."},"solutions":{"mission":"Translate a real business workflow into a defensible AI design and delivery plan. Bring application, data, platform, security and operations choices together and expose assumptions before committing to scale.","day":["Discover workflow and data constraints with stakeholders","Compare architectures and test the riskiest assumption","Define acceptance criteria, cost boundaries and handover ownership"],"entry":"Build broad cloud, networking, identity, data and application architecture skills plus enough Python/API practice to validate a design. Architecture roles often expect prior delivery ownership; a diagram alone does not demonstrate implementation judgment.","concepts":["architecture","lifecycle","retrieval","evaluation","identity","unitcost","slo","agentstate","platform"],"tools":{"Start here":["python","docker","mlflow","opentofu"],"Compare alternatives":["terraform","pgvector","litellm"],"Add when needed":["otel","langgraph"]},"stack":"A small executable workflow + an evaluation dataset + an architecture decision record. Choose a model API and a simple retrieval store only if the problem requires them.","managed":"Compare AWS, Azure and Google Cloud using the actual use case. Include OCI or existing Databricks/Snowflake estates when relevant; do not force feature-by-feature equivalence across providers.","clouds":["aws-bedrock","aws-sagemaker","aws-agentcore","azure-foundry","azure-ml","azure-search","gcp-platform","gcp-agents","gcp-rag","oci-genai","databricks","snowflake"],"queries":["AI Solutions Architect","Generative AI Architect","Cloud AI Architect","AI Platform Architect"],"phases":[{"name":"Discover the use case","tasks":["Write the workflow and non-AI baseline","Identify data owners, users and prohibited actions","Set quality, latency, cost and availability goals"],"artifact":"Discovery brief and acceptance owners","gate":"Explain why AI is useful and when a simpler approach is preferable."},{"name":"Compare feasible designs","tasks":["Draw data, control and execution paths","Compare managed/self-hosted and retrieval/tuning choices","Document assumptions, identity and failure boundaries"],"artifact":"Two-option ADR and risk register","gate":"Eliminate designs that violate hard constraints before comparing convenience."},{"name":"Test the riskiest assumption","tasks":["Build a narrow proof of concept","Evaluate representative cases and permission boundaries","Measure workload cost and latency with stated limits"],"artifact":"Runnable prototype and evidence report","gate":"Use measured results to revise the design; distinguish simulated from production evidence."},{"name":"Plan delivery and ownership","tasks":["Define staged rollout, monitoring and rollback","Assign security, data and operations owners","Prepare a cost model, runbooks and handover"],"artifact":"Delivery plan and architecture review pack","gate":"Every acceptance criterion has evidence or an explicitly unresolved validation task."}],"interview":[{"question":"How do you choose RAG versus fine-tuning?","lookFor":"Diagnose knowledge freshness, task behavior, data availability and evaluation evidence; they can be complementary."},{"question":"What makes a managed-versus-self-hosted comparison credible?","lookFor":"Same workload and quality constraints, full cost and operational responsibilities, region/privacy requirements and tested assumptions."},{"question":"How do you keep a proof of concept from becoming unsupported production?","lookFor":"Explicit acceptance gates, owners, identity/network controls, monitoring, rollback and a funded operating model."}],"resume":"Delivered an AI architecture decision pack with a runnable prototype, measured acceptance results, cost assumptions and named operational responsibilities."}}};
